CREATE DATABASE IF NOT EXISTS RS;
USE RS;
CREATE TABLE IF NOT EXISTS rooms(room_id INT PRIMARY KEY AUTO_INCREMENT,room_number INT UNIQUE NOT NULL,room_type VARCHAR(30) NOT NULL,price_per_night DECIMAL(10,2) NOT NULL,status VARCHAR(20) DEFAULT 'AVAILABLE');
CREATE TABLE IF NOT EXISTS guests(guest_id INT PRIMARY KEY AUTO_INCREMENT,guest_name VARCHAR(100) NOT NULL,contact_no VARCHAR(15) NOT NULL,email VARCHAR(100));
CREATE TABLE IF NOT EXISTS reservations(reservation_id INT PRIMARY KEY AUTO_INCREMENT,guest_id INT NOT NULL,room_id INT NOT NULL,check_in DATE NOT NULL,check_out DATE NOT NULL,status VARCHAR(20) DEFAULT 'BOOKED',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(guest_id) REFERENCES guests(guest_id),FOREIGN KEY(room_id) REFERENCES rooms(room_id),CHECK(check_out>check_in));
CREATE TABLE IF NOT EXISTS payments(payment_id INT PRIMARY KEY AUTO_INCREMENT,reservation_id INT UNIQUE NOT NULL,amount DECIMAL(10,2) NOT NULL,payment_status VARCHAR(20) DEFAULT 'PENDING',payment_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(reservation_id) REFERENCES reservations(reservation_id));
